  "Box Breathing / Parasympathetic Reset": "Respiración cuadrada / Reinicio parasimpático",
  "Box breathing: inhale for 4 seconds, hold for 4, exhale for 4, and rest for 4.": "Respiración cuadrada: inhala durante 4 segundos, retén 4, exhala 4 y descansa 4.",
  "Brass Details": "Detalles de latón",
  "Breaks initial inertia.": "Rompe la inercia inicial.",
  "Breakthrough": "Avance decisivo",
  "Breathe In": "Inhala",
  "Breathe Out": "Exhala",
  "Breathe deeply and slowly. Confident people breathe slowly. Let your breath teach your body.": "Respira lenta y profundamente. Las personas seguras respiran despacio. Deja que tu respiración enseñe a tu cuerpo.",
  "Breathe deeply. Approach your next task with calm, centered poise.": "Respira hondo. Aborda tu próxima tarea con calma, equilibrio y serenidad.",
  "Breathe in for four. Out for six. Let the breathing slow down the mind.": "Inhala contando hasta cuatro. Exhala hasta seis. Deja que la respiración calme la mente.",
  "Breathe in for four... hold for four... and out for six. Slow the whole system down.": "Inhala contando hasta cuatro... retén hasta cuatro... y exhala hasta seis. Desacelera todo tu sistema.",
  "Breathe in gently... and let out a long, slow exhale. Let each breath be a little slower than the last.": "Inhala suavemente... y suelta el aire en una exhalación larga y lenta. Deja que cada respiración sea un poco más lenta que la anterior.",
  "Breathe in joy. Breathe out heaviness. Breathe in lightness. Breathe out worry.": "Inhala alegría. Exhala pesadez. Inhala ligereza. Exhala preocupación.",
  "Breathe in power. Breathe out excuses. Breathe in fire. Breathe out hesitation.": "Inhala fuerza. Exhala excusas. Inhala fuego. Exhala dudas.",
  "Breathe in strength. Breathe out doubt. One more time.": "Inhala fortaleza. Exhala dudas. Una vez más.",
  "Breathe in through your nose. Breathe out slowly. Let your weight sink downward, rooted and stable.": "Inhala por la nariz. Exhala despacio. Deja que tu peso descienda, firme y estable.",
  "Breathe in, and imagine the breath is light. Breathe out, and let that light spread through your chest.": "Inhala e imagina que el aire es luz. Exhala y deja que esa luz se extienda por tu pecho.",
  "Breathe in. Feel the stillness. Breathe out. Let the noise settle like dust in a quiet room.": "Inhala. Siente la quietud. Exhala. Deja que el ruido se asiente como el polvo en una habitación tranquila.",
  "Breathe in... and go. Now.": "Inhala... y actúa. Ahora.",
  "Breathe into that place. And as you exhale, imagine the story loosening, like an old rope untying.": "Lleva la respiración a ese lugar. Y al exhalar, imagina que esa historia se afloja, como una cuerda vieja que se desata.",
  "Breathe out the day. It's done. You showed up.": "Deja ir el día al exhalar. Ya ha terminado. Estuviste presente.",
  "Breathe slowly. In through the nose. Out through the mouth. Let the shoulders drop.": "Respira despacio. Entra por la nariz. Sale por la boca. Deja caer los hombros.",
  "Breathe slowly. With each breath, thank your lungs, quietly, for doing this without being asked.": "Respira despacio. Con cada respiración, agradece en silencio a tus pulmones que hagan esto sin que se lo pidas.",
  "Breathe slowly. With each exhale, let today loosen its grip. You are about to travel forward in time.": "Respira despacio. Con cada exhalación, deja que el día de hoy afloje su agarre. Estás a punto de viajar al futuro.",
  "Breathe. The mind is quiet. The task is clear. The body is ready.": "Respira. La mente está en calma. La tarea está clara. El cuerpo está preparado.",
  "Breathe... and drift.": "Respira... y déjate llevar.",
  "Breathing, meditation & mental space decluttering": "Respiración, meditación y orden mental",
  "Bridge \"{name}\" to a real savings and execution plan.": "Conecta \"{name}\" con un plan real de ahorro y acción.",
  "Brief context on what belongs here.": "Breve contexto de lo que va aquí.",
  "Bright red 1970s coupé, analog everything, pop-up joy.": "Un cupé rojo intenso de los años 70, todo analógico, alegría con faros escamoteables.",
  "Bring to mind a moment when you felt truly good. A laugh. A sunrise. A hug. A win.": "Recuerda un momento en que te sentiste realmente bien. Una risa. Un amanecer. Un abrazo. Una victoria.",
  "Bring to mind one doubt you carry. A sentence that starts with \"I can't\", or \"I am not the kind of person who...\"": "Piensa en una duda que llevas contigo. Una frase que empieza por \"No puedo\", o \"No soy de las personas que...\"",
  "Bring your attention to the top of your head. Let the scalp soften. Let the forehead smooth out.": "Lleva la atención a la parte superior de tu cabeza. Deja que el cuero cabelludo se relaje. Deja que la frente se alise.",
