  "Fear Then Freedom": "Primero miedo, después libertad",
  "Fear is a poor long-term fuel, but a clear picture of the default path is a superb compass. Make it concrete, count what it costs, and notice the small moments you drift toward it.": "El miedo es un mal combustible a largo plazo, pero una imagen clara del camino por defecto es una brújula excelente. Concrétalo, calcula lo que cuesta y detecta los pequeños momentos en que te desvías hacia él.",
  "Fear of putting out work and having it meet total silence.": "Miedo a publicar tu trabajo y encontrar un silencio absoluto.",
  "Feature it in your Daily Vision Affirmations on the Home page and on your Vision Board.": "Inclúyelo en tus afirmaciones diarias de visión de la página de inicio y en tu Tablero de Visión.",
  "Featured Curations": "Selecciones destacadas",
  "Feedback & Iteration": "Comentarios y mejora continua",
  "Feel Good": "Sentirse bien",
  "Feel a quiet strength in your chest. Confidence is not loud. It is calm.": "Siente una fuerza silenciosa en el pecho. La confianza no hace ruido. Es serena.",
  "Feel a steady strength rising from the ground, up through your legs, into your spine. Quiet. Certain.": "Siente una fuerza estable que asciende desde el suelo, por tus piernas, hasta la columna. Silenciosa. Segura.",
  "Feel energy building in your chest. A warm pressure. That is your drive. It was never gone, only buried.": "Siente cómo crece la energía en tu pecho. Una presión cálida. Ese es tu impulso. Nunca desapareció, solo estaba enterrado.",
  "Feel it in your hands. They want to work. Feel it in your legs. They want to stand.": "Siéntelo en las manos. Quieren trabajar. Siéntelo en las piernas. Quieren ponerse en pie.",
  "Feel the corners of your mouth lift a little more. Your body believes what you show it.": "Siente cómo las comisuras de tu boca se elevan un poco más. Tu cuerpo cree lo que le muestras.",
  "Feel the warmth in your chest expanding. Gratitude is not a thought. It is a feeling in the body.": "Siente cómo se expande la calidez en tu pecho. La gratitud no es un pensamiento. Es una sensación en el cuerpo.",
  "Feel the weight of that evidence. You are not pretending. You are remembering.": "Siente el peso de esas pruebas. No estás fingiendo. Estás recordando.",
  "Feel this future in your body now. It is not a wish. It is a memory of something coming.": "Siente ahora este futuro en tu cuerpo. No es un deseo. Es el recuerdo de algo que está por llegar.",
  "Feel your attention narrowing, like a lens coming into focus. Sharp. Bright. Still.": "Siente cómo tu atención se concentra, como una lente que enfoca. Nítida. Luminosa. Quieta.",
  "Feel your eyes growing heavier. Your face softening. Your jaw releasing.": "Siente cómo pesan más los párpados. Cómo se suaviza el rostro. Cómo se relaja la mandíbula.",
  "Feel your finances. Calm. Enough. Growing. Money is a tool in your hands, not a weight on your chest.": "Siente tus finanzas. Calma. Suficiencia. Crecimiento. El dinero es una herramienta en tus manos, no un peso en el pecho.",
  "Feel your shoulders drop away from your ears. Let them become heavy.": "Siente cómo los hombros se alejan de las orejas. Deja que pesen.",
  "Feel-Good Boost": "Impulso de bienestar",
