  "Note:": "Nota:",
  "Nothing found to archive.": "No se ha encontrado nada que archivar.",
  "Notice any restlessness in your body. The urge to check, to scroll, to reach for something. Just notice it.": "Observa cualquier inquietud en tu cuerpo. Las ganas de consultar, de deslizar, de buscar algo. Solo obsérvalas.",
  "Notice how they hold their shoulders. Their eyes. The pace of their words. Feel it in your own body now.": "Observa cómo coloca los hombros. Sus ojos. El ritmo de sus palabras. Siéntelo ahora en tu propio cuerpo.",
  "Notice the home you live in. Walk through it slowly. Touch the surfaces. Feel how it feels to be here.": "Observa la casa en la que vives. Recórrela despacio. Toca las superficies. Siente cómo es estar aquí.",
  "Notice where that doubt lives in your body. A tightness. A heaviness. Just locate it.": "Observa dónde vive esa duda en tu cuerpo. Una tensión. Un peso. Solo localízala.",
  "Notice your body. How do you carry yourself? How do you move, breathe, stand?": "Observa tu cuerpo. ¿Cómo te sostienes? ¿Cómo te mueves, respiras, te quedas de pie?",
  "Notice: nothing outside you changed. Only what you looked at. This is a superpower.": "Observa: nada fuera de ti ha cambiado. Solo aquello a lo que mirabas. Esto es un superpoder.",
  "Notice: the urge is already softer. You are stronger than the pull.": "Observa: el impulso ya es más suave. Eres más fuerte que esa atracción.",
  "Noticed {n} resistance thoughts.": "Has detectado {n} pensamientos de resistencia.",
  "Notification permission granted.": "Permiso de notificaciones concedido.",
  "Notifications are blocked in the browser. Allow them to receive nudges.": "El navegador bloquea las notificaciones. Permítelas para recibir recordatorios.",
  "Now": "Ahora",
  "Now find your future self in this life. Look into their eyes. They are calm, clear, and proud of you.": "Ahora encuentra a tu yo del futuro en esta vida. Mírale a los ojos. Transmite calma, claridad y orgullo por ti.",
  "Now it is three years. The projects you were going to start are still ideas. Notice what you stopped mentioning to people.": "Ahora han pasado tres años. Los proyectos que ibas a empezar siguen siendo ideas. Observa qué has dejado de mencionar a los demás.",
  "Now name your one task. Only one. Say it silently, clearly, as a single sentence.": "Ahora nombra tu única tarea. Solo una. Dila en silencio, con claridad, en una sola frase.",
  "Now recognize: this is not truth. It is a story. Someone, or something, taught it to you.": "Ahora reconoce esto: no es la verdad. Es una historia. Alguien, o algo, te la enseñó.",
  "Now simply rest in this stillness. Nothing to fix. Nothing to chase. Just breathing.": "Ahora simplemente descansa en esta quietud. Nada que arreglar. Nada que perseguir. Solo respirar.",
  "Now think of something small from today. A taste. A sound. A moment of comfort. Thank it.": "Ahora piensa en algo pequeño de hoy. Un sabor. Un sonido. Un momento de comodidad. Agradécelo.",
  "Now turn around. Walk back to the fork. Feel each step getting lighter.": "Ahora date la vuelta. Regresa a la bifurcación. Siente cómo cada paso se vuelve más ligero.",
  "Now, from this place, look back at today. What is the one decision that moved you onto this road?": "Ahora, desde aquí, vuelve la vista a hoy. ¿Cuál fue la decisión que te puso en este camino?",
  "Now, why are you doing this? Not the small reason. The real one. Who are you becoming? Who are you doing it for?": "Ahora, ¿por qué haces esto? No el motivo pequeño. El verdadero. ¿En quién te estás convirtiendo? ¿Por quién lo haces?",
