  "Say silently: For the next session, this is the only thing that exists.": "Di en silencio: Durante la próxima sesión, esto es lo único que existe.",
  "Say silently: I am allowed to feel good today. I do not have to earn it. It is already mine.": "Di en silencio: Puedo sentirme bien hoy. No tengo que ganármelo. Ya me pertenece.",
  "Say silently: I am becoming this person, one decision at a time.": "Di en silencio: Me estoy convirtiendo en esta persona, una decisión a la vez.",
