  "Sit at your workspace. Close your eyes. In six minutes you will begin the most important work of your day.": "Siéntate en tu espacio de trabajo. Cierra los ojos. En seis minutos empezarás el trabajo más importante de tu día.",
  "Sit comfortably and close your eyes. In this session, you will visit the life you are building.": "Siéntate cómodamente y cierra los ojos. En esta sesión visitarás la vida que estás construyendo.",
  "Sit down and close your eyes. This walk has two halves. The first one is not comfortable, and that is the point.": "Siéntate y cierra los ojos. Este recorrido tiene dos partes. La primera no es cómoda, y esa es la intención.",
  "Sit up straight. Spine tall. Chin level. This session is not for resting. It is for igniting.": "Siéntate con la espalda recta. Alarga la columna. Mantén la barbilla nivelada. Esta sesión no es para descansar. Es para encender tu impulso.",
  "Sit with the stillness. Let your baseline come back up. You are recalibrating.": "Quédate en la quietud. Deja que tu nivel de equilibrio se recupere. Te estás reajustando.",
  "Six Seats": "Seis plazas",
  "Six full months of living expenses untouched in liquid reserves, giving complete autonomy over career choices.": "Seis meses completos de gastos de vida intactos en reservas líquidas, que te dan total autonomía para elegir tu carrera.",
  "Sixty seconds of freefall from 4,000 m — fear, then the widest view of your life.": "Sesenta segundos de caída libre desde 4.000 m — miedo, y después la vista más amplia de tu vida.",
  "Skeletonized Calibre 3132": "Calibre 3132 esqueletado",
  "Skeletonized slate-grey dial revealing the patented double balance wheel mechanism in stainless steel with hand-finished bevels.": "Esfera esqueletada gris pizarra que revela el mecanismo patentado de doble volante, en acero inoxidable con biseles acabados a mano.",
