  "Take a photo from your camera and jot down your mental state, execution win, or vision reflection.": "Haz una foto con la cámara y anota tu estado mental, un logro concreto o una reflexión sobre tu visión.",
  "Take a slow breath in through your nose... and let it out through your mouth, like a long sigh.": "Inspira despacio por la nariz... y suelta el aire por la boca, como un suspiro largo.",
