  "Take one deeper breath. When you are ready, gently open your eyes, carrying this calm with you.": "Respira un poco más hondo. Cuando estés listo, abre los ojos suavemente y lleva esta calma contigo.",
  "Take one strong breath in. Let it out slowly.": "Inspira con fuerza. Suelta el aire despacio.",
