  "The daily reality you are actively working toward.": "La realidad cotidiana hacia la que trabajas activamente.",
  "The default future is built by accident. The built future is built before 10am.": "El futuro por defecto se construye por accidente. El futuro elegido se construye antes de las 10.",
  "The desk is clearing. Feel the space appearing. Quiet. Clean. Ready.": "El escritorio se despeja. Siente cómo aparece el espacio. Tranquilo. Limpio. Preparado.",
  "The dive watch that became the standard — 300 m, ceramic bezel, Oystersteel.": "El reloj de buceo que se convirtió en referente — 300 m, bisel cerámico, Oystersteel.",
  "The doubt may return. That is fine. Now you know it is only a story, and you are the author.": "Puede que la duda vuelva. Está bien. Ahora sabes que solo es una historia, y tú la escribes.",
  "The dream on your board is a few hundred good afternoons away. This is one of them.": "El sueño de tu tablero está a unos cientos de buenas tardes. Esta es una de ellas.",
  "The environment does half the discipline for you.": "El entorno hace por ti la mitad del trabajo de disciplina.",
  "The environment you tolerate is the ceiling of what you will achieve.": "El entorno que toleras marca el techo de lo que lograrás.",
  "The everyday supercar: flat-six, manual option, and a shape refined for sixty years.": "El superdeportivo de cada día: seis cilindros bóxer, opción manual y una silueta perfeccionada durante sesenta años.",
