  "The freedom to disappear in comfort.": "La libertad de desaparecer con comodidad.",
  "The frequency of transformation and love; releases heaviness in the chest and opens gratitude.": "La frecuencia de la transformación y el amor; libera el peso del pecho y abre paso a la gratitud.",
  "The friction you anticipate is almost always larger than the physical task itself.": "La resistencia que anticipas casi siempre es mayor que la tarea física en sí.",
  "The future belongs to those who believe in the beauty of their dreams and back it with unrelenting craft.": "El futuro pertenece a quienes creen en la belleza de sus sueños y los respaldan con un trabajo incansable.",
  "The future you're building is one good night's sleep closer.": "El futuro que construyes está una buena noche de sueño más cerca.",
