  "The future, daily.": "El futuro, cada día.",
  "The highest form of respect you can pay to {dName} is honoring the hours between now and its arrival with deep, undistracted craft.": "La mayor muestra de respeto que puedes ofrecer a {dName} es honrar las horas que faltan hasta su llegada con un trabajo profundo y sin distracciones.",
  "The hour when your daily focus checkpoint prompt appears.": "La hora a la que aparece tu recordatorio diario de concentración.",
  "The impediment to action advances action. What stands in the way becomes the way.": "El obstáculo a la acción impulsa la acción. Lo que se interpone en el camino se convierte en el camino.",
