  "The life you're building": "La vida que estás construyendo",
  "The luxury SUV benchmark: air suspension, executive rear seats, and a presence that needs no badge.": "El referente de los SUV de lujo: suspensión neumática, asientos traseros ejecutivos y una presencia que no necesita emblemas.",
  "The market rewards specific knowledge, extreme reliability, and courage in negotiation.": "El mercado recompensa el conocimiento específico, la fiabilidad extrema y el valor al negociar.",
  "The mind is everything. What you think you become.": "La mente lo es todo. Te conviertes en lo que piensas.",
  "The mountains from above, in an hour.": "Las montañas desde arriba, en una hora.",
  "The next single domino to set up tomorrow.": "La siguiente ficha de dominó que preparar mañana.",
  "The one that stops traffic.": "El que hace que todos se detengan a mirar.",
  "The only person you are destined to become is the person you decide to be.": "La única persona en la que estás destinado a convertirte es la que decides ser.",
  "The perfectionist procrastinator": "Quien posterga por perfeccionismo",
  "The person you're becoming shows up in the next hour. Let them.": "La persona en la que te conviertes aparece en la próxima hora. Déjala aparecer.",
  "The real price": "El precio real",
  "The root frequency; releases buried anxiety, guilt and mental weight.": "La frecuencia raíz; libera la ansiedad enterrada, la culpa y el peso mental.",
  "The scroll will still be there. The momentum won't. Choose momentum.": "El contenido seguirá ahí. El impulso no. Elige el impulso.",
  "The sea as your living room.": "El mar como salón.",
  "The secret of getting ahead is getting started.": "El secreto para avanzar es empezar.",
  "The shield": "El escudo",
  "The speed of your transition to {dName} is strictly determined by the velocity of your daily decisions.": "La rapidez con la que llegas a {dName} depende directamente del ritmo de tus decisiones diarias.",
  "The streak is safe if you kept your word. If not, tomorrow is a clean page.": "La racha está a salvo si cumpliste tu palabra. Si no, mañana es una página en blanco.",
