  "The version that waits for perfect certainty before publishing.": "La versión que espera una certeza perfecta antes de publicar.",
  "Theatre": "Teatro",
  "There is no penalty for missed days — only the quiet math of where your days go.": "No hay penalizaciones por los días perdidos — solo la cuenta silenciosa de adónde van tus días.",
  "Thermal Camper": "Autocaravana térmica",
