  "Theta Waves": "Ondas theta",
  "Think back over today. Find one thing you did well, even something small. Let yourself feel it.": "Repasa el día de hoy. Encuentra algo que hayas hecho bien, aunque sea pequeño. Permítete sentirlo.",
  "Think of a hard time that taught you something. Somehow it made you who you are. Thank it too.": "Piensa en una etapa difícil que te enseñó algo. De algún modo te hizo quien eres. Dale las gracias también.",
  "Think of one meaningful thing you are building. A goal that actually matters to you.": "Piensa en algo importante que estés construyendo. Un objetivo que de verdad te importe.",
  "Think of one person who has helped you. See their face. Feel a warm thank you rise toward them.": "Piensa en alguien que te haya ayudado. Mira su rostro. Siente cómo surge hacia esa persona un agradecimiento cálido.",
  "Think of something in your home that makes your life easier. Something you rarely notice. Thank it.": "Piensa en algo de tu casa que te haga la vida más fácil. Algo en lo que apenas reparas. Agradécelo.",
  "Think of the old self. The one who apologized for taking up space. Thank them, and let them go.": "Piensa en tu antiguo yo. Ese que se disculpaba por ocupar espacio. Dale las gracias y déjalo ir.",
  "Think of the very next action. Not the whole project. The next fifteen minutes. See yourself starting.": "Piensa en la acción que viene ahora. No en todo el proyecto. En los próximos quince minutos. Imagínate empezando.",
  "Think of your body. Whatever it can do today, it is carrying you. Thank it for that.": "Piensa en tu cuerpo. Sea lo que sea que pueda hacer hoy, te sostiene. Dale las gracias por ello.",
  "Thinking space, designed on purpose.": "Espacio para pensar, diseñado con intención.",
  "Thirty days in Kyoto and Tokyo ryokans, learning traditional craftsmanship, bullet train expeditions, and tea ceremonies.": "Treinta días en ryokans de Kyoto y Tokyo, aprendiendo artesanía tradicional, haciendo excursiones en tren bala y participando en ceremonias del té.",
  "This Month": "Este mes",
  "This Week, In 30 Seconds": "Esta semana, en 30 segundos",
  "This file is packaged locally inside your browser and downloaded straight to your machine. No external servers or analytics track your backup.": "Este archivo se prepara localmente en tu navegador y se descarga directamente a tu equipo. Ningún servidor externo ni sistema de analítica rastrea tu copia de seguridad.",
  "This is who you are now. Every choice today comes from this place.": "Esta es la persona que eres ahora. Cada elección de hoy nace de aquí.",
  "This mission was completed less than 2 hours ago. Your consistency is noted, but repeat rewards require spaced action.": "Esta misión se completó hace menos de 2 horas. Tu constancia cuenta, pero las recompensas repetidas requieren acciones espaciadas.",
  "This will permanently wipe your Dream Bank ledger, completed missions history, custom items, and Two Futures statements from your local device.": "Esto borrará permanentemente de tu dispositivo el registro del Banco de Sueños, el historial de misiones completadas, tus elementos personalizados y tus declaraciones de Dos Futuros.",
  "Thoughts may drift by. Let them go, like leaves on a slow river.": "Puede que pasen pensamientos. Déjalos ir, como hojas en un río tranquilo.",
