  "Three days of indoor pools looking into the forest, massages, sauna and food that fixes you.": "Tres días de piscinas interiores con vistas al bosque, masajes, sauna y comida que te recupera.",
  "Three nights chasing the aurora with a photographer-guide and a thermal camper.": "Tres noches tras las auroras con un guía fotógrafo y una autocaravana térmica.",
  "Three nights over the marina, boats lit up below, brunch and a desert dune dinner.": "Tres noches sobre el puerto deportivo, barcos iluminados abajo, brunch y una cena entre dunas del desierto.",
