  "Three years from now — if nothing changes": "Dentro de tres años — si nada cambia",
  "Three years. The work is real now. The money is calmer. Someone you respect just told you they are proud of you.": "Tres años. El trabajo ya es real. El dinero da más tranquilidad. Alguien a quien respetas acaba de decirte que siente orgullo por ti.",
