  "True luxury is alignment with your highest vision. The existence of {dName} on your horizon is a compass, not a fantasy.": "El verdadero lujo es estar en sintonía con tu visión más alta. La presencia de {dName} en tu horizonte es una brújula, no una fantasía.",
