  "Waiting for ideal conditions is subtle procrastination. Excellence thrives within constraints.": "Esperar las condiciones ideales es una forma sutil de postergar. La excelencia crece dentro de los límites.",
  "Wake the fire and move": "Enciende el fuego y muévete",
  "Wake up rushed, commute with friction, do reactive tasks, return drained.": "Despertarte con prisas, sufrir el trayecto, trabajar a golpe de urgencias y volver sin energía.",
  "Wake up with a clear calendar, two hours of deep creation, afternoon training, evening reading.": "Despertarte con la agenda despejada, dos horas de creación profunda, entrenamiento por la tarde y lectura por la noche.",
  "Walk back through the door, bringing the feeling with you. Nothing is lost. It is all ahead.": "Vuelve a cruzar la puerta y trae contigo esa sensación. No has perdido nada. Todo está por delante.",
  "Walk honestly through the default future first, feel its weight, then cross over into the life you are building. Ends with one decision.": "Recorre primero con honestidad el futuro por defecto, siente su peso y después cruza a la vida que estás construyendo. Termina con una decisión.",
  "Walk the Cornish coast path and shortlist three plots.": "Recorre el sendero costero de Cornwall y selecciona tres parcelas.",
  "Walking into the boutique to collect the watch you waited a year for.": "Entrar en la boutique a recoger el reloj que has esperado durante un año.",
  "Wall-to-wall glass living room over the river and bridges, quiet study, and a rooftop terrace with a fire pit.": "Salón con paredes enteras de cristal sobre el río y los puentes, estudio tranquilo y terraza en la azotea con brasero.",
  "Warm 18k rose gold case with embossed brown dial, self-winding caliber 26-330 S C, and integrated satin-finished bracelet.": "Cálida caja de oro rosa de 18k con esfera marrón en relieve, calibre automático 26-330 S C y brazalete integrado con acabado satinado.",
  "Warm 18k rose gold case, chocolate embossed horizontal dial, mechanical self-winding caliber 26-330 S C.": "Cálida caja de oro rosa de 18k, esfera chocolate con relieve horizontal y calibre mecánico automático 26-330 S C.",
