  "Warming Up": "Preparación",
  "Warmth flows down your arms, into your hands, all the way to your fingertips.": "El calor baja por tus brazos, llega a las manos y recorre hasta la punta de los dedos.",
  "Warmth, ease and a life that fits in sandals.": "Calidez, comodidad y una vida que se vive en sandalias.",
  "Waste no more time arguing about what a good person should be. Be one.": "No pierdas más tiempo discutiendo cómo debe ser una buena persona. Sé una.",
  "Watches": "Relojes",
  "We believe personal growth software should never use manipulative streaks, pay-to-win shortcuts, or disguised real-money gambling. Dream Dollars is strictly earned through real-world actions.": "Creemos que el software de crecimiento personal nunca debe usar rachas manipuladoras, atajos de pago para ganar ni apuestas con dinero real encubiertas. Los Dream Dollars se ganan exclusivamente con acciones en el mundo real.",
  "We suffer more often in imagination than in reality.": "Sufrimos más a menudo en la imaginación que en la realidad.",
