  "What Avoidance Protects:": "Lo que protege la evitación:",
  "What Money Lets You Say No To:": "A qué te permite decir no el dinero:",
  "What action did you take today? How did you overcome friction? What does this mean for your future life?": "¿Qué acción has realizado hoy? ¿Cómo has superado los obstáculos? ¿Qué significa esto para tu vida futura?",
  "What are you known for, and by whom?": "¿Por qué te conocen y quiénes te conocen por ello?",
  "What decision, vision moment, or realization happened?": "¿Qué decisión, momento de visión o descubrimiento ha ocurrido?",
  "What dissatisfaction have you quietly agreed to live with?": "¿Con qué insatisfacción has aceptado vivir en silencio?",
  "What do you complain about but never actually take action to change?": "¿De qué te quejas sin hacer nunca nada para cambiarlo?",
  "What does financial autonomy let you say \"no\" to?": "¿A qué te permite decir \"no\" la autonomía financiera?",
  "What fear, discomfort, or judgment are your current avoidance habits protecting you from?": "¿De qué miedo, incomodidad o juicio te protegen tus hábitos actuales de evitación?",
  "What fueled your focus or caused friction today? (e.g. 7 hours uninterrupted sleep, box breathing session, deep work win)...": "¿Qué ha favorecido tu concentración o creado obstáculos hoy? (p. ej. 7 horas de sueño sin interrupciones, sesión de respiración cuadrada, logro de trabajo profundo)...",
  "What happens if you change nothing for 5 to 10 years.": "Qué ocurre si no cambias nada durante 5 a 10 años.",
  "What is that protection actually costing you in time, dignity, and potential?": "¿Cuánto te está costando realmente esa protección en tiempo, dignidad y potencial?",
  "What is the first physical move that connects this dream to reality?": "¿Cuál es el primer movimiento físico que conecta este sueño con la realidad?",
  "What is the one decision that would make today meaningful?": "¿Cuál es la decisión que haría que hoy tuviera sentido?",
  "What makes today meaningful:": "Lo que da sentido a hoy:",
  "What we achieve inwardly will change outer reality.": "Lo que logramos por dentro cambiará la realidad exterior.",
  "Whatever came, hold it. That is your instruction for today.": "Sea lo que sea que haya surgido, consérvalo. Esa es tu indicación para hoy.",
  "Whatever you avoided yesterday is the One Decision for today.": "Lo que evitaste ayer es la Decisión de hoy.",
  "When you voluntarily embrace physical effort, modern mental stress loses its power over your nervous system.": "Cuando aceptas voluntariamente el esfuerzo físico, el estrés mental actual pierde poder sobre tu sistema nervioso.",
  "When your emotional anchor to your future life is vivid, momentary discomfort fades.": "Cuando el vínculo emocional con tu vida futura es intenso, la incomodidad momentánea se desvanece.",
  "When your inner identity is anchored in {futureRole}, the physical manifestation of {dName} is merely a matter of time and calm persistence.": "Cuando tu identidad interior se afianza en {futureRole}, la materialización de {dName} es solo cuestión de tiempo y perseverancia serena.",
  "Where you place your gaze determines the emotional tone and trajectory of your day.": "Donde pones la mirada determina el tono emocional y el rumbo de tu día.",
  "Which doors are closed for good? Who did you become to the people who depend on you? What is the one sentence you would say about the last decade?": "¿Qué puertas se han cerrado para siempre? ¿En quién te has convertido para quienes dependen de ti? ¿Qué frase dirías sobre la última década?",
  "Which opportunities did you watch other people take? What does your body feel like? What do you tell yourself at 11pm?": "¿Qué oportunidades has visto aprovechar a otros? ¿Cómo se siente tu cuerpo? ¿Qué te dices a las 23:00?",
  "Which outdated version of yourself would you need to let go of to change?": "¿Qué versión anticuada de ti tendrías que dejar atrás para cambiar?",
